  class synx_ctl_socket #(synx_param_t P = SYNX_PARAM_DEFAULT) extends fw_socket #(synx_req_if #(P), synx_rsp_if #(P));
      function new(string name, fw_component parent, synx_rsp_if #(P) imp = null);
          super.new(name, parent, imp);
      endfunction
  endclass

  // The per's API endpoint on a component: calls synx_rsp_if, provides synx_req_if. Its peer
  // is the ctl's (connect()); connect_up() exposes it one level out.
  class synx_per_socket #(synx_param_t P = SYNX_PARAM_DEFAULT) extends fw_mirror #(synx_req_if #(P), synx_rsp_if #(P));
      function new(string name, fw_component parent, synx_req_if #(P) imp = null);
          super.new(name, parent, imp);
      endfunction
  endclass

  // Listeners attached by path to the abstractor handles of this P. A test
  // registers listeners for a path (add; either may be null); each handle
  // registers its proxies under its path when it is built (attach). Whichever
  // comes second joins them, so the order does not matter as long as both come
  // before the traffic. unused() names the listener paths no handle took (a
  // misspelled path, another P).
  class synx_observers #(synx_param_t P = SYNX_PARAM_DEFAULT);
      static string m_path[$];
      static synx_req_if_listener #(P) m_req[$];
      static synx_rsp_if_listener #(P) m_rsp[$];
      static bit m_used[$];
      static string m_h_path[$];
      static synx_req_if_proxy #(P) m_h_req[$];
      static synx_rsp_if_proxy #(P) m_h_rsp[$];

      static function void pair(int unsigned i, synx_req_if_proxy #(P) req, synx_rsp_if_proxy #(P) rsp);
          if (m_req[i] != null) req.add_listener(m_req[i]);
          if (m_rsp[i] != null) rsp.add_listener(m_rsp[i]);
          m_used[i] = 1;
      endfunction

      static function void add(string path, synx_req_if_listener #(P) req, synx_rsp_if_listener #(P) rsp);
          m_path.push_back(path);
          m_req.push_back(req);
          m_rsp.push_back(rsp);
          m_used.push_back(0);
          foreach (m_h_path[h]) if (m_h_path[h] == path)
              pair(m_path.size() - 1, m_h_req[h], m_h_rsp[h]);
      endfunction

      static function void attach(string path, synx_req_if_proxy #(P) req, synx_rsp_if_proxy #(P) rsp);
          m_h_path.push_back(path);
          m_h_req.push_back(req);
          m_h_rsp.push_back(rsp);
          foreach (m_path[i]) if (m_path[i] == path) pair(i, req, rsp);
      endfunction

      // The listener paths no handle has taken, comma-separated; "" if none.
      static function string unused();
          string s;
          foreach (m_path[i]) if (!m_used[i]) s = {s, (s == "") ? "" : ", ", m_path[i]};
          return s;
      endfunction
  endclass

  /* verilator lint_off UNUSEDSIGNAL */
  // Description of an abstractor whose pins play ctl (synx_ctl_xtor): it stands
  // behind a per endpoint and drives an RTL per port. Inserted by
  // synx_per_sp::connect(). Nothing runs through it: in the description its
  // synx_req_if methods never return; at run time synx_ctl_abs_h replaces it.
  class synx_ctl_abs #(synx_param_t P = SYNX_PARAM_DEFAULT) extends fw_boundary implements synx_req_if #(P);
      typedef synx_req_if #(P)::cmd_t cmd_t;
      synx_ctl_sp #(P) sp;
      /* verilator lint_off UNDRIVEN */      // never triggered, by design
      event m_never;
      /* verilator lint_on UNDRIVEN */

      function new(string name, fw_component parent);
          super.new(name, parent);
          sp = new("sp", this);
      endfunction

      // Stand behind the parent's endpoint.
      function void serve(synx_per_socket #(P) ep);
          ep.set_imp(this);
          m_serves = ep.get_name();
      endfunction

      virtual task cmd(input cmd_t t);
          @m_never;
      endtask

      virtual function fw_sp_base pin_sp(); return sp; endfunction
      virtual function string xtor_module(); return "synx_ctl_xtor"; endfunction
      virtual function string vif_type();
          return {"virtual synx_ctl_xtor_if #(", sp.param_lit(), ")"};
      endfunction
      virtual function string handle_type();
          return {"synx_ctl_abs_h #(", sp.param_lit(), ")"};
      endfunction
      virtual function string xtor_clk_rst(); return ".clk(clock), .rst(reset)"; endfunction
  endclass
  /* verilator lint_on UNUSEDSIGNAL */

  /* verilator lint_off UNUSEDSIGNAL */
  // Description of an abstractor whose pins play per (synx_per_xtor): it stands
  // behind a ctl endpoint and drives an RTL ctl port. Inserted by
  // synx_ctl_sp::connect(). Nothing runs through it: in the description its
  // synx_rsp_if methods never return; at run time synx_per_abs_h replaces it.
  class synx_per_abs #(synx_param_t P = SYNX_PARAM_DEFAULT) extends fw_boundary implements synx_rsp_if #(P);
      typedef synx_rsp_if #(P)::rsp_t rsp_t;
      synx_per_sp #(P) sp;
      /* verilator lint_off UNDRIVEN */      // never triggered, by design
      event m_never;
      /* verilator lint_on UNDRIVEN */

      function new(string name, fw_component parent);
          super.new(name, parent);
          sp = new("sp", this);
      endfunction

      // Stand behind the parent's endpoint.
      function void serve(synx_ctl_socket #(P) ep);
          ep.set_imp(this);
          m_serves = ep.get_name();
      endfunction

      virtual task rsp(input rsp_t t);
          @m_never;
      endtask

      virtual function fw_sp_base pin_sp(); return sp; endfunction
      virtual function string xtor_module(); return "synx_per_xtor"; endfunction
      virtual function string vif_type();
          return {"virtual synx_per_xtor_if #(", sp.param_lit(), ")"};
      endfunction
      virtual function string handle_type();
          return {"synx_per_abs_h #(", sp.param_lit(), ")"};
      endfunction
      virtual function string xtor_clk_rst(); return ".clk(clock), .rst(reset)"; endfunction
  endclass
  /* verilator lint_on UNUSEDSIGNAL */

  // Run time: the abstractor synx_ctl_abs, as a component. Calls made on the
  // endpoint go through req to the pins (synx_ctl_xtor_bridge); what the pins receive goes
  // through rsp to the endpoint's peer. Listeners attach to req and rsp.
  // Knobs set for its path in fw_proto_cfg ("<ch>.depth", "<ch>.max_gap")
  // reach the channel transactors when it starts. Listeners registered for its
  // path (synx_observers) are added to its proxies.
  class synx_ctl_abs_h #(synx_param_t P = SYNX_PARAM_DEFAULT) extends fw_component implements fw_runnable;
      synx_ctl_xtor_bridge #(P) bridge;
      synx_req_if_proxy #(P) req;
      synx_rsp_if_proxy #(P) rsp;
      synx_per_socket #(P) m_ep;

      function new(string name, fw_component parent, virtual synx_ctl_xtor_if #(P) vif);
          super.new(name, parent);
          rsp = new();
          bridge = new(vif, rsp);
          req = new(bridge);
          synx_observers #(P)::attach(fw_rel_path(this), req, rsp);
          parent.add_runnable(this);
      endfunction

      function void serve(synx_per_socket #(P) ep);
          m_ep = ep;
          ep.set_imp(req);
      endfunction

      virtual task run();
          string path = fw_rel_path(this);
          string names[$];
          rsp.m_target = m_ep.t;
          wait (bridge.vif.bound);
          fw_proto_cfg::names(path, names);
          foreach (names[i])
              if (!bridge.vif.chans.set_knob(names[i], fw_proto_cfg::get_int(path, names[i], 0)))
                  $error("%s: no knob '%s'", path, names[i]);
          bridge.run();
      endtask
  endclass

  // Run time: the abstractor synx_per_abs, as a component. Calls made on the
  // endpoint go through rsp to the pins (synx_per_xtor_bridge); what the pins receive goes
  // through req to the endpoint's peer. Listeners attach to rsp and req.
